int vhost_iotlb_add_range_ctx ( struct vhost_iotlb * iotlb , u64 start , u64 last , u64 addr , unsigned int perm , void * opaque ) { struct vhost_iotlb_map * map ; if ( last < start ) { return - EFAULT ; } if ( start == 0 && last == ULONG_MAX ) { u64 mid = last / 2 ; int err = vhost_iotlb_add_range_ctx ( iotlb , start , mid , addr , perm , opaque ) ; if ( err ) { return err ; } addr += mid + 1 ; start = mid + 1 ; } if ( iotlb -> limit && iotlb -> nmaps == iotlb -> limit && iotlb -> flags & VHOST_IOTLB_FLAG_RETIRE ) { map = list_first_entry ( & iotlb -> list , typeof ( * map ) , link ) ; vhost_iotlb_map_free ( iotlb , map ) ; } map = kmalloc ( sizeof ( * map ) , GFP_ATOMIC ) ; map -> start = start ; map -> size = last - start + 1 ; map -> last = last ; map -> addr = addr ; map -> perm = perm ; map -> opaque = opaque ; iotlb -> nmaps ++ ; vhost_iotlb_itree_insert ( map , & iotlb -> root ) ; INIT_LIST_HEAD ( & map -> link ) ; list_add_tail ( & map -> link , & iotlb -> list ) ; return 0 ; } 